<?php require __DIR__.'/bootstrap.php';$u=require_login();header('Content-Type: application/json; charset=utf-8');
if($_SERVER['REQUEST_METHOD']==='POST'){ $msg=trim($_POST['message']??'');if($msg===''){http_response_code(422);echo json_encode(['error'=>'Mensagem vazia']);exit;}if(mb_strlen($msg)>1000)$msg=mb_substr($msg,0,1000);$pdo->prepare('INSERT INTO community_messages(user_id,message) VALUES(?,?)')->execute([$u['id'],$msg]);$id=(int)$pdo->lastInsertId();if($u['role']!=='member'){$pdo->prepare("INSERT INTO audit_logs(user_id,action,metadata) VALUES(?,?,?)")->execute([$u['id'],'community_message',json_encode(['message_id'=>$id])]);}echo json_encode(['ok'=>true,'id'=>$id]);exit;}
$after=max(0,(int)($_GET['after']??0));$limit=min(80,max(1,(int)($_GET['limit']??50)));$q=$pdo->prepare("SELECT m.id,m.message,m.created_at,u.name,u.role FROM community_messages m JOIN users u ON u.id=m.user_id WHERE m.status='visible' AND m.id>? ORDER BY m.id ASC LIMIT $limit");$q->execute([$after]);echo json_encode(['messages'=>$q->fetchAll()]);
